import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Question","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/question.md","filePath":"03-developer/models/question.md"}`),a={name:`03-developer/models/question.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="question" tabindex="-1">Question <a class="header-anchor" href="#question" aria-label="Permalink to “Question”">​</a></h1><p>The <code>Question</code> model is used to record customers&#39; questions about products. These questions may concern product specifications, features, or related services. For example, a customer might ask whether a product includes after-sales service or what the shoulder width of a garment is.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique question ID</td></tr><tr><td><code>body</code></td><td>TEXT</td><td>No</td><td>Customer&#39;s question</td></tr><tr><td><code>customer_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the customer who submitted the question</td></tr><tr><td><code>answer</code></td><td>TEXT</td><td>Yes</td><td>Answer submitted to the question; may be empty</td></tr><tr><td><code>product_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the product the question is about</td></tr><tr><td><code>status</code></td><td>TINYINT</td><td>No</td><td>Question status, with a value of <code>0</code> or <code>1</code></td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Question creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Last update time</td></tr></tbody></table><h2 id="relationships" tabindex="-1">Relationships <a class="header-anchor" href="#relationships" aria-label="Permalink to “Relationships”">​</a></h2><ul><li><code>product()</code>: A <code>belongsTo</code> relationship with the <code>Product</code> model; the product the question is about.</li><li><code>customer()</code>: A <code>belongsTo</code> relationship with the <code>Customer</code> model; the customer who submitted the question.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="product" tabindex="-1"><code>product()</code> <a class="header-anchor" href="#product" aria-label="Permalink to “product()”">​</a></h3><p>Returns the product associated with the question.</p><h3 id="customer" tabindex="-1"><code>customer()</code> <a class="header-anchor" href="#customer" aria-label="Permalink to “customer()”">​</a></h3><p>Returns the customer who submitted the question.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Questions are associated with a specific product and are not designed for general questions about the site.</li><li>The answer is stored in the <code>answer</code> field and is optional.</li><li>If a customer or product is deleted, the related questions are also deleted according to the database&#39;s foreign key constraints.</li><li>The <code>status</code> field accepts the values <code>0</code> and <code>1</code>; the precise meaning of each value is not specified in this document.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};